<script setup>
import { reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import { ArrowRight, Eye, EyeOff, Home, KeyRound, Mail, ShieldCheck, Sparkles } from 'lucide-vue-next';
import api, { apiError } from '../services/api';
import { useAuthStore } from '../stores/auth';
const auth = useAuthStore(); const router = useRouter(); const mode = ref('login'); const showPassword = ref(false); const notice = ref(''); const error = ref('');
const form = reactive({ name: '', email: 'admin@homeerp.test', phone: '', password: 'password', password_confirmation: '' });
const submit = async () => { error.value = ''; notice.value = ''; try { if (mode.value === 'login') { await auth.login({ email: form.email, password: form.password }); router.push('/'); } else if (mode.value === 'register') { await api.post('/auth/register', form); mode.value = 'login'; notice.value = 'Account created. Sign in to continue.'; } else { await api.post('/auth/forgot-password', { email: form.email }); notice.value = 'If that email is registered, a reset link has been sent.'; } } catch (e) { error.value = apiError(e); } };
</script>
<template>
    <div class="mesh-bg flex min-h-screen items-center justify-center overflow-hidden px-4 py-8 text-white"><div class="pointer-events-none absolute -left-32 top-10 h-80 w-80 rounded-full bg-emerald-400/10 blur-3xl"></div><div class="pointer-events-none absolute -right-24 bottom-0 h-96 w-96 rounded-full bg-cyan-500/10 blur-3xl"></div><div class="grid w-full max-w-5xl overflow-hidden rounded-[2rem] border border-emerald-100/15 bg-[#082421]/80 shadow-2xl backdrop-blur-xl lg:grid-cols-[1.05fr_.95fr]">
        <section class="relative hidden min-h-[620px] overflow-hidden border-r border-emerald-100/10 p-10 lg:flex lg:flex-col lg:justify-between"><div class="absolute -right-24 top-20 h-64 w-64 rounded-full border border-emerald-200/20 shadow-[0_0_80px_rgba(99,230,190,.18)]"></div><div class="absolute right-12 top-32 h-40 w-40 rotate-12 rounded-[2.5rem] border border-cyan-200/30 bg-gradient-to-br from-emerald-300/20 to-cyan-300/5 shadow-[inset_0_0_40px_rgba(155,246,210,.12),0_25px_70px_rgba(0,0,0,.3)]"></div><div class="absolute right-24 top-44 h-20 w-20 rounded-full bg-emerald-200/20 blur-xl"></div><div class="relative"><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-2xl bg-emerald-200 text-[#062421]"><Home :size="19" /></span><span class="text-sm font-bold tracking-[.2em]">NOVA HOME</span></div><p class="eyebrow mt-20">Household intelligence, spatially organized</p><h1 class="mt-4 max-w-md text-5xl font-semibold leading-[1.05] tracking-tight">Your home.<br><span class="text-emerald-200">Your command center.</span></h1><p class="mt-6 max-w-sm text-sm leading-6 text-[#8db5a8]">A private 3D operating system for the people, places, and moments that make a house feel like home.</p></div><div class="relative flex items-center gap-3 text-xs text-[#7ba99a]"><span class="flex h-8 w-8 items-center justify-center rounded-xl bg-emerald-200/10 text-emerald-200"><ShieldCheck :size="15" /></span> Your data stays permission-scoped to your household.</div></section>
        <section class="p-6 sm:p-10 lg:p-14"><div class="mb-10 lg:hidden"><div class="flex items-center gap-3"><span class="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-200 text-[#062421]"><Home :size="17" /></span><span class="text-sm font-bold tracking-[.2em]">NOVA HOME</span></div></div><div class="mb-8"><p class="eyebrow flex items-center gap-2"><Sparkles :size="13" /> {{ mode === 'login' ? 'Welcome back' : mode === 'register' ? 'Create your household' : 'Password recovery' }}</p><h2 class="mt-3 text-3xl font-semibold tracking-tight">{{ mode === 'login' ? 'Sign in to your home.' : mode === 'register' ? 'Start your smart home ERP.' : 'Reset your access.' }}</h2><p class="mt-2 text-sm text-[#7da397]">{{ mode === 'login' ? 'Your household is ready when you are.' : 'Set up an account and your private 3D workspace.' }}</p></div><form class="space-y-4" @submit.prevent="submit"><div v-if="mode === 'register'"><label class="label">Full name</label><input v-model="form.name" class="field" required placeholder="Your name" /></div><div><label class="label">Email address</label><div class="relative"><Mail :size="16" class="absolute left-3 top-1/2 -translate-y-1/2 text-[#5d887c]"/><input v-model="form.email" type="email" class="field pl-9" required placeholder="you@example.com" /></div></div><div v-if="mode === 'register'"><label class="label">Mobile</label><input v-model="form.phone" class="field" placeholder="+91 98765 43210" /></div><div v-if="mode !== 'forgot'"><div class="flex items-center justify-between"><label class="label">Password</label><button v-if="mode === 'login'" type="button" class="mb-2 text-[11px] text-emerald-200/70 hover:text-emerald-100" @click="mode = 'forgot'">Forgot password?</button></div><div class="relative"><KeyRound :size="16" class="absolute left-3 top-1/2 -translate-y-1/2 text-[#5d887c]"/><input v-model="form.password" :type="showPassword ? 'text' : 'password'" class="field pl-9 pr-10" required placeholder="Your password"/><button type="button" class="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-[#6c998c]" @click="showPassword = !showPassword"><EyeOff v-if="showPassword" :size="16"/><Eye v-else :size="16"/></button></div></div><input v-if="mode === 'register'" v-model="form.password_confirmation" type="password" class="field" required minlength="8" placeholder="Confirm password"/><p v-if="error" class="rounded-xl border border-rose-300/20 bg-rose-400/10 px-3 py-2 text-xs text-rose-200">{{ error }}</p><p v-if="notice" class="rounded-xl border border-emerald-300/20 bg-emerald-300/10 px-3 py-2 text-xs text-emerald-100">{{ notice }}</p><button class="btn-primary mt-2 w-full" :disabled="auth.loading">{{ auth.loading ? 'Please wait…' : mode === 'login' ? 'Enter my home' : mode === 'register' ? 'Create account' : 'Send reset link' }}<ArrowRight :size="16" /></button></form><div class="mt-7 flex items-center justify-between text-xs text-[#719b8e]"><button v-if="mode === 'login'" class="hover:text-emerald-100" @click="mode = 'register'">New here? Create an account</button><button v-else class="hover:text-emerald-100" @click="mode = 'login'">Back to sign in</button><span class="hidden sm:block">Demo: admin@homeerp.test</span></div></section>
    </div></div>
</template>
